    "content": "#ifndef OV_COMMON_H\n#define OV_COMMON_H\n\n#ifndef UNICODE\n#define UNICODE\n#endif\n#ifndef _UNICODE\n#define _UNICODE\n#endif\n#ifndef COBJMACROS\n#define COBJMACROS\n#endif\n#ifndef _WIN32_WINNT\n#define _WIN32_WINNT 0x0A00\n#endif\n#ifndef WINVER\n#define WINVER 0x0A00\n#endif\n\n#include <winsock2.h>\n#include <ws2tcpip.h>\n#include <windows.h>\n#include <stdint.h>\n#include <stdbool.h>\n#include <wchar.h>\n\nstatic inline void ov_wcscpy(wchar_t* dst, size_t cap, const wchar_t* src) {\n    if (!dst || cap == 0) return;\n    if (!src) {\n        dst[0] = L'\\0';\n        return;\n    }\n    wcsncpy(dst, src, cap - 1);\n    dst[cap - 1] = L'\\0';\n}\n\n#define MAX_CANDLES         2048\n#define MAX_WATCHLIST       64\n#define MAX_WL_SECTIONS     16\n#define MAX_DRAWINGS        256\n#define MAX_ALERTS          64\n#define MAX_ALERT_CONDS     8\n#define MAX_ALERT_LOGS      128\n#define RING_CAPACITY       1024\n\n#define WM_APP_FEED_TICK      (WM_APP + 101)\n#define WM_APP_SOURCE_STATE   (WM_APP + 102)\n#define WM_APP_ALERT_FIRED    (WM_APP + 103)\n#define WM_APP_SNAPSHOT_READY (WM_APP + 104)\n\ntypedef enum {\n    SRC_BINANCE  = 0,\n    SRC_COINBASE = 1,\n    SRC_KRAKEN   = 2,\n    SRC_COUNT    = 3\n} FeedSourceId;\n\ntypedef enum {\n    TF_1M  = 60,\n    TF_5M  = 300,\n    TF_15M = 900,\n    TF_1H  = 3600,\n    TF_4H  = 14400,\n    TF_1D  = 86400,\n    TF_1W  = 604800,\n    TF_1MO = 2592000,\n    TF_1Y  = 31536000\n} TimeframeSec;\n\ntypedef struct {\n    int64_t      time_utc;\n    double       open;\n    double       high;\n    double       low;\n    double       close;\n    double       volume;\n    FeedSourceId source;\n} CandleBar;\n\ntypedef struct {\n    uint32_t id;\n    wchar_t  name[48];\n    bool     collapsed;\n} WatchlistSection;\n\ntypedef struct {\n    uint32_t id;\n    uint32_t section_id;\n    wchar_t  symbol[24];\n    wchar_t  name[48];\n    wchar_t  display_name[48];\n    double   price;\n    double   open_24h;\n    double   high_24h;\n    double   low_24h;\n    double   volume_24h;\n    double   change_pct;\n    double   source_prices[SRC_COUNT];\n    int64_t  last_update_ms;\n    bool     removed;\n} WatchlistItem;\n\ntypedef struct {\n    wchar_t      symbol[24];\n    FeedSourceId source;\n    double       price;\n    double       volume;\n    int64_t      timestamp_ms;\n} FeedTick;\n\ntypedef enum {\n    STATE_OFFLINE = 0,\n    STATE_SYNCING,\n    STATE_LIVE,\n    STATE_FALLBACK\n} SourceConnState;\n\ntypedef struct {\n    FeedSourceId    id;\n    wchar_t         label[24];\n    wchar_t         endpoint[64];\n    SourceConnState state;\n    uint32_t        latency_ms;\n    uint64_t        ticks_received;\n} SourceStatusInfo;\n\nstatic inline const wchar_t* ov_tf_label(TimeframeSec tf) {\n    switch (tf) {\n        case TF_1M:  return L\"1m\";\n        case TF_5M:  return L\"5m\";\n        case TF_15M: return L\"15m\";\n        case TF_1H:  return L\"1h\";\n        case TF_4H:  return L\"4h\";\n        case TF_1D:  return L\"1d\";\n        case TF_1W:  return L\"1S\";\n        case TF_1MO: return L\"1M\";\n        case TF_1Y:  return L\"1A\";\n        default:     return L\"15m\";\n    }\n}\n\nstatic inline const wchar_t* ov_tf_code(TimeframeSec tf) {\n    switch (tf) {\n        case TF_1M:  return L\"1m\";\n        case TF_5M:  return L\"5m\";\n        case TF_15M: return L\"15m\";\n        case TF_1H:  return L\"1h\";\n        case TF_4H:  return L\"4h\";\n        case TF_1D:  return L\"1d\";\n        case TF_1W:  return L\"1w\";\n        case TF_1MO: return L\"1M\";\n        case TF_1Y:  return L\"1y\";\n        default:     return L\"15m\";\n    }\n}\n\n#endif /* OV_COMMON_H */\n"
