  {
    "path": "src/indicators.c",
    "name": "indicators.c",
    "category": "source",
    "language": "c",
    "summary": "Calculs EMA, SMA, Bollinger, RSI (Wilder) et MACD avec activation individuelle.",
    "content": "#include \"indicators.h\"\n#include <math.h>\n#include <string.h>\n\nvoid indicators_default_settings(IndicatorSettings* cfg) {\n    cfg->enable_ema_fast = true;\n    cfg->enable_ema_slow = true;\n    cfg->enable_sma      = false;\n    cfg->enable_bb       = false;\n    cfg->enable_rsi      = true;\n    cfg->enable_macd     = false;\n\n    cfg->ema_fast_period = 12;\n    cfg->ema_slow_period = 26;\n    cfg->sma_period      = 50;\n    cfg->bb_period       = 20;\n    cfg->bb_stddev       = 2.0;\n    cfg->rsi_period      = 14;\n    cfg->macd_fast       = 12;\n    cfg->macd_slow       = 26;\n    cfg->macd_signal     = 9;\n}\n\nint indicators_active_count(const IndicatorSettings* cfg) {\n    int n = 0;\n    if (cfg->enable_ema_fast) n++;\n    if (cfg->enable_ema_slow) n++;\n    if (cfg->enable_sma)      n++;\n    if (cfg->enable_bb)       n++;\n    if (cfg->enable_rsi)      n++;\n    if (cfg->enable_macd)     n++;\n    return n;\n}\n\nstatic void calc_sma(\n    const CandleBar* bars,\n    size_t count,\n    int period,\n    double* out,\n    bool* valid\n) {\n    memset(valid, 0, sizeof(bool) * count);\n    if (period <= 0 || count < (size_t)period) return;\n    double sum = 0.0;\n    for (size_t i = 0; i < count; i++) {\n        sum += bars[i].close;\n        if (i >= (size_t)period) sum -= bars[i - period].close;\n        if (i >= (size_t)(period - 1)) {\n            out[i]   = sum / (double)period;\n            valid[i] = true;\n        }\n    }\n}\n\nstatic void calc_ema_values(\n    const double* input,\n    size_t count,\n    int period,\n    double* out,\n    bool* valid\n) {\n    memset(valid, 0, sizeof(bool) * count);\n    if (period <= 0 || count < (size_t)period) return;\n    double k   = 2.0 / ((double)period + 1.0);\n    double sum = 0.0;\n    for (int i = 0; i < period; i++) sum += input[i];\n    double ema = sum / (double)period;\n    out[period - 1]   = ema;\n    valid[period - 1] = true;\n\n    for (size_t i = (size_t)period; i < count; i++) {\n        ema      = input[i] * k + ema * (1.0 - k);\n        out[i]   = ema;\n        valid[i] = true;\n    }\n}\n\nstatic void calc_bollinger(\n    const CandleBar* bars,\n    size_t count,\n    int period,\n    double mult,\n    IndicatorBuffers* out\n) {\n    calc_sma(bars, count, period, out->bb_mid, out->valid_bb);\n    if (period <= 0 || count < (size_t)period) return;\n    for (size_t i = (size_t)(period - 1); i < count; i++) {\n        double mean = out->bb_mid[i];\n        double sq   = 0.0;\n        for (size_t j = i - (size_t)period + 1; j <= i; j++) {\n            double d = bars[j].close - mean;\n            sq += d * d;\n        }\n        double sd = sqrt(sq / (double)period);\n        out->bb_upper[i] = mean + mult * sd;\n        out->bb_lower[i] = mean - mult * sd;\n    }\n}\n\nstatic void calc_rsi(\n    const CandleBar* bars,\n    size_t count,\n    int period,\n    double* out,\n    bool* valid\n) {\n    memset(valid, 0, sizeof(bool) * count);\n    if (period <= 0 || count <= (size_t)period) return;\n    double avg_gain = 0.0, avg_loss = 0.0;\n    for (int i = 1; i <= period; i++) {\n        double d = bars[i].close - bars[i - 1].close;\n        if (d >= 0.0) avg_gain += d;\n        else avg_loss -= d;\n    }\n    avg_gain /= (double)period;\n    avg_loss /= (double)period;\n    out[period]   = (avg_loss == 0.0) ? 100.0 : (100.0 - 100.0 / (1.0 + avg_gain / avg_loss));\n    valid[period] = true;\n\n    for (size_t i = (size_t)(period + 1); i < count; i++) {\n        double d    = bars[i].close - bars[i - 1].close;\n        double gain = d > 0.0 ? d : 0.0;\n        double loss = d < 0.0 ? -d : 0.0;\n        avg_gain    = (avg_gain * (period - 1) + gain) / (double)period;\n        avg_loss    = (avg_loss * (period - 1) + loss) / (double)period;\n        out[i]      = (avg_loss == 0.0) ? 100.0 : (100.0 - 100.0 / (1.0 + avg_gain / avg_loss));\n        valid[i]    = true;\n    }\n}\n\nvoid indicators_compute_all(\n    const CandleBar* bars,\n    size_t count,\n    const IndicatorSettings* cfg,\n    IndicatorBuffers* out\n) {\n    ZeroMemory(out, sizeof(*out));\n    if (count == 0 || !cfg) return;\n    if (count > MAX_CANDLES) count = MAX_CANDLES;\n\n    double closes[MAX_CANDLES];\n    for (size_t i = 0; i < count; i++) closes[i] = bars[i].close;\n\n    calc_ema_values(closes, count, cfg->ema_fast_period, out->ema_fast, out->valid_ema_fast);\n    calc_ema_values(closes, count, cfg->ema_slow_period, out->ema_slow, out->valid_ema_slow);\n    calc_sma(bars, count, cfg->sma_period, out->sma, out->valid_sma);\n    calc_bollinger(bars, count, cfg->bb_period, cfg->bb_stddev, out);\n    calc_rsi(bars, count, cfg->rsi_period, out->rsi, out->valid_rsi);\n\n    double fast[MAX_CANDLES], slow[MAX_CANDLES];\n    bool vf[MAX_CANDLES], vs[MAX_CANDLES];\n    calc_ema_values(closes, count, cfg->macd_fast, fast, vf);\n    calc_ema_values(closes, count, cfg->macd_slow, slow, vs);\n\n    double macd_compact[MAX_CANDLES];\n    size_t macd_idx[MAX_CANDLES];\n    size_t m_cnt = 0;\n\n    for (size_t i = 0; i < count; i++) {\n        if (vf[i] && vs[i]) {\n            out->macd_line[i]   = fast[i] - slow[i];\n            macd_compact[m_cnt] = out->macd_line[i];\n            macd_idx[m_cnt]     = i;\n            m_cnt++;\n        }\n    }\n\n    if (m_cnt >= (size_t)cfg->macd_signal) {\n        double sig[MAX_CANDLES];\n        bool vsig[MAX_CANDLES];\n        calc_ema_values(macd_compact, m_cnt, cfg->macd_signal, sig, vsig);\n        for (size_t j = 0; j < m_cnt; j++) {\n            if (vsig[j]) {\n                size_t orig = macd_idx[j];\n                out->macd_signal[orig] = sig[j];\n                out->macd_hist[orig]   = out->macd_line[orig] - sig[j];\n                out->valid_macd[orig]  = true;\n            }\n        }\n    }\n}\n"
  },
  {
    "path": "src/drawings.c",
    "name": "drawings.c",
    "category": "source",
    "language": "c",
    "summary": "Gestion des dessins par token, annulation et sauvegarde/chargement JSON UTF-8.",
    "content": "#include \"drawings.h\"\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nvoid drawings_init(DrawingStore* store) {\n    ZeroMemory(store, sizeof(*store));\n    store->next_id = 1;\n}\n\nuint32_t drawings_add(\n    DrawingStore* store,\n    uint32_t entry_id,\n    const wchar_t* symbol,\n    DrawingToolKind kind,\n    const AnchorPoint* pts,\n    size_t pt_count,\n    uint32_t argb_color,\n    float stroke_width,\n    DrawingLineStyle line_style,\n    const wchar_t* label\n) {\n    if (store->count >= MAX_DRAWINGS || pt_count == 0 || pt_count > 3) {\n        return 0;\n    }\n    ChartDrawing* d = &store->items[store->count++];\n    ZeroMemory(d, sizeof(*d));\n    d->id = store->next_id++;\n    d->entry_id = entry_id;\n    ov_wcscpy(d->symbol, 24, symbol);\n    d->kind = kind;\n    d->pt_count = pt_count;\n    for (size_t i = 0; i < pt_count; i++) d->pts[i] = pts[i];\n    d->argb_color    = argb_color;\n    d->stroke_width  = (stroke_width > 0.2f) ? stroke_width : 1.8f;\n    d->line_style    = line_style;\n    d->label_align_h = (kind == TOOL_TRENDLINE || kind == TOOL_CHANNEL) ? ALIGN_H_CENTER : ALIGN_H_LEFT;\n    d->label_align_v = ALIGN_V_TOP;\n    d->locked        = false;\n    if (label) {\n        ov_wcscpy(d->label, 64, label);\n    }\n    return d->id;\n}\n\nChartDrawing* drawings_find_by_id(DrawingStore* store, uint32_t id) {\n    for (size_t i = 0; i < store->count; i++) {\n        if (store->items[i].id == id) return &store->items[i];\n    }\n    return NULL;\n}\n\nbool drawings_remove_by_id(DrawingStore* store, uint32_t id) {\n    for (size_t i = 0; i < store->count; i++) {\n        if (store->items[i].id == id) {\n            for (size_t j = i; j + 1 < store->count; j++) {\n                store->items[j] = store->items[j + 1];\n            }\n            store->count--;\n            return true;\n        }\n    }\n    return false;\n}\n\nbool drawings_matches_scope(\n    const ChartDrawing* d,\n    uint32_t entry_id,\n    const wchar_t* symbol,\n    bool is_primary_entry\n) {\n    if (!d || !symbol) return false;\n    if (d->entry_id != 0) {\n        if (entry_id != 0) return d->entry_id == entry_id;\n        return wcscmp(d->symbol, symbol) == 0;\n    }\n    return wcscmp(d->symbol, symbol) == 0 && is_primary_entry;\n}\n\nbool drawings_undo_scope(\n    DrawingStore* store,\n    uint32_t entry_id,\n    const wchar_t* symbol,\n    bool is_primary_entry\n) {\n    for (size_t i = store->count; i > 0; i--) {\n        if (drawings_matches_scope(&store->items[i - 1], entry_id, symbol, is_primary_entry)) {\n            return drawings_remove_by_id(store, store->items[i - 1].id);\n        }\n    }\n    return false;\n}\n\nvoid drawings_clear_scope(\n    DrawingStore* store,\n    uint32_t entry_id,\n    const wchar_t* symbol,\n    bool is_primary_entry\n) {\n    size_t write_idx = 0;\n    for (size_t i = 0; i < store->count; i++) {\n        if (!drawings_matches_scope(&store->items[i], entry_id, symbol, is_primary_entry)) {\n            store->items[write_idx++] = store->items[i];\n        }\n    }\n    store->count = write_idx;\n}\n\nvoid drawings_remove_by_entry(DrawingStore* store, uint32_t entry_id) {\n    if (entry_id == 0) return;\n    size_t write_idx = 0;\n    for (size_t i = 0; i < store->count; i++) {\n        if (store->items[i].entry_id != entry_id) {\n            store->items[write_idx++] = store->items[i];\n        }\n    }\n    store->count = write_idx;\n}\n\nbool drawings_undo_symbol(DrawingStore* store, const wchar_t* symbol) {\n    for (size_t i = store->count; i > 0; i--) {\n        if (wcscmp(store->items[i - 1].symbol, symbol) == 0) {\n            return drawings_remove_by_id(store, store->items[i - 1].id);\n        }\n    }\n    return false;\n}\n\nvoid drawings_clear_symbol(DrawingStore* store, const wchar_t* symbol) {\n    size_t write_idx = 0;\n    for (size_t i = 0; i < store->count; i++) {\n        if (wcscmp(store->items[i].symbol, symbol) != 0) {\n            store->items[write_idx++] = store->items[i];\n        }\n    }\n    store->count = write_idx;\n}\n\nsize_t drawings_count_symbol(const DrawingStore* store, const wchar_t* symbol) {\n    size_t cnt = 0;\n    for (size_t i = 0; i < store->count; i++) {\n        if (wcscmp(store->items[i].symbol, symbol) == 0) cnt++;\n    }\n    return cnt;\n}\n\nstatic void write_utf8_str(HANDLE h, const char* s) {\n    DWORD written = 0;\n    WriteFile(h, s, (DWORD)strlen(s), &written, NULL);\n}\n\nstatic void write_json_escaped(HANDLE h, const wchar_t* ws) {\n    char utf8[256];\n    WideCharToMultiByte(CP_UTF8, 0, ws ? ws : L\"\", -1, utf8, sizeof(utf8), NULL, NULL);\n    write_utf8_str(h, \"\\\"\");\n    for (const char* p = utf8; *p; p++) {\n        if (*p == '\"' || *p == '\\\\') {\n            char esc[3] = { '\\\\', *p, '\\0' };\n            write_utf8_str(h, esc);\n        } else if ((unsigned char)*p >= 0x20) {\n            DWORD w = 0;\n            WriteFile(h, p, 1, &w, NULL);\n        }\n    }\n    write_utf8_str(h, \"\\\"\");\n}\n\nbool drawings_save_file_w(const DrawingStore* store, const wchar_t* file_path) {\n    HANDLE h = CreateFileW(\n        file_path, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL\n    );\n    if (h == INVALID_HANDLE_VALUE) return false;\n\n    write_utf8_str(h, \"[\\n\");\n    for (size_t i = 0; i < store->count; i++) {\n        const ChartDrawing* d = &store->items[i];\n        char buf[256];\n        write_utf8_str(h, \"  {\\\"symbol\\\":\");\n        write_json_escaped(h, d->symbol);\n        snprintf(\n            buf, sizeof(buf),\n            \",\\\"entry_id\\\":%u,\\\"kind\\\":%d,\\\"color\\\":%u,\\\"width\\\":%.2f,\\\"style\\\":%d,\\\"align_h\\\":%d,\\\"align_v\\\":%d,\\\"locked\\\":%s,\\\"label\\\":\",\n            (unsigned)d->entry_id,\n            (int)d->kind,\n            (unsigned)d->argb_color,\n            d->stroke_width,\n            (int)d->line_style,\n            (int)d->label_align_h,\n            (int)d->label_align_v,\n            d->locked ? \"true\" : \"false\"\n        );\n        write_utf8_str(h, buf);\n        write_json_escaped(h, d->label);\n        write_utf8_str(h, \",\\\"pts\\\":[\");\n        for (size_t p = 0; p < d->pt_count; p++) {\n            snprintf(\n                buf, sizeof(buf),\n                \"{\\\"t\\\":%lld,\\\"p\\\":%.8f}%s\",\n                (long long)d->pts[p].time_utc,\n                d->pts[p].price,\n                (p + 1 < d->pt_count) ? \",\" : \"\"\n            );\n            write_utf8_str(h, buf);\n        }\n        write_utf8_str(h, (i + 1 < store->count) ? \"]}\\n,\" : \"]}\\n\");\n    }\n    write_utf8_str(h, \"]\\n\");\n    CloseHandle(h);\n    return true;\n}\n\nstatic bool extract_json_str(const char* obj, const char* key, wchar_t* out, size_t cap) {\n    char pat[64];\n    snprintf(pat, sizeof(pat), \"\\\"%s\\\":\\\"\", key);\n    const char* p = strstr(obj, pat);\n    if (!p) return false;\n    p += strlen(pat);\n    char utf8[256];\n    size_t idx = 0;\n    while (*p && *p != '\"' && idx + 1 < sizeof(utf8)) {\n        if (*p == '\\\\' && p[1]) p++;\n        utf8[idx++] = *p++;\n    }\n    utf8[idx] = '\\0';\n    MultiByteToWideChar(CP_UTF8, 0, utf8, -1, out, (int)cap);\n    return true;\n}\n\nbool drawings_load_file_w(DrawingStore* store, const wchar_t* file_path) {\n    HANDLE h = CreateFileW(\n        file_path, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL\n    );\n    if (h == INVALID_HANDLE_VALUE) return false;\n\n    DWORD sz = GetFileSize(h, NULL);\n    if (sz == INVALID_FILE_SIZE || sz == 0 || sz > 2 * 1024 * 1024) {\n        CloseHandle(h);\n        return false;\n    }\n\n    char* buf = (char*)malloc((size_t)sz + 1);\n    if (!buf) {\n        CloseHandle(h);\n        return false;\n    }\n    DWORD got = 0;\n    BOOL ok = ReadFile(h, buf, sz, &got, NULL);\n    CloseHandle(h);\n    if (!ok || got == 0) {\n        free(buf);\n        return false;\n    }\n    buf[got] = '\\0';\n\n    drawings_init(store);\n    const char* cur = buf;\n    while ((cur = strstr(cur, \"{\\\"symbol\\\":\")) != NULL && store->count < MAX_DRAWINGS) {\n        const char* next_obj = strstr(cur + 10, \"{\\\"symbol\\\":\");\n        size_t span = next_obj ? (size_t)(next_obj - cur) : strlen(cur);\n        char* obj = (char*)malloc(span + 1);\n        if (!obj) break;\n        memcpy(obj, cur, span);\n        obj[span] = '\\0';\n\n        wchar_t sym[24] = L\"\";\n        wchar_t lbl[64] = L\"\";\n        extract_json_str(obj, \"symbol\", sym, 24);\n        extract_json_str(obj, \"label\", lbl, 64);\n\n        unsigned entry_id = 0;\n        int kind = 1, style = 0;\n        int align_h = -1, align_v = 0;\n        unsigned color = 0xFF2962FFU;\n        double width = 1.8;\n        const char* peid = strstr(obj, \"\\\"entry_id\\\":\");\n        if (peid) entry_id = (unsigned)strtoul(peid + 11, NULL, 10);\n        const char* pk = strstr(obj, \"\\\"kind\\\":\");\n        if (pk) kind = atoi(pk + 7);\n        const char* pc = strstr(obj, \"\\\"color\\\":\");\n        if (pc) color = (unsigned)strtoul(pc + 8, NULL, 10);\n        const char* pw = strstr(obj, \"\\\"width\\\":\");\n        if (pw) width = strtod(pw + 8, NULL);\n        const char* ps = strstr(obj, \"\\\"style\\\":\");\n        if (ps) style = atoi(ps + 8);\n        const char* pah = strstr(obj, \"\\\"align_h\\\":\");\n        if (pah) align_h = atoi(pah + 10);\n        const char* pav = strstr(obj, \"\\\"align_v\\\":\");\n        if (pav) align_v = atoi(pav + 10);\n        bool locked = (strstr(obj, \"\\\"locked\\\":true\") != NULL);\n\n        AnchorPoint pts[3];\n        size_t pt_count = 0;\n        const char* ppts = strstr(obj, \"\\\"pts\\\":[\");\n        if (ppts) {\n            const char* pt_it = ppts;\n            while (pt_count < 3 && (pt_it = strstr(pt_it, \"{\\\"t\\\":\")) != NULL) {\n                long long t = strtoll(pt_it + 5, NULL, 10);\n                const char* pp = strstr(pt_it, \"\\\"p\\\":\");\n                double pr = pp ? strtod(pp + 4, NULL) : 0.0;\n                pts[pt_count].time_utc = (int64_t)t;\n                pts[pt_count].price    = pr;\n                pt_count++;\n                pt_it += 5;\n            }\n        }\n\n        if (sym[0] && pt_count > 0) {\n            uint32_t id = drawings_add(\n                store, (uint32_t)entry_id, sym, (DrawingToolKind)kind, pts, pt_count,\n                (uint32_t)color, (float)width, (DrawingLineStyle)style, lbl\n            );\n            ChartDrawing* added = drawings_find_by_id(store, id);\n            if (added) {\n                added->locked = locked;\n                if (align_h >= 0 && align_h <= 2) added->label_align_h = (DrawingLabelAlignH)align_h;\n                if (align_v >= 0 && align_v <= 2) added->label_align_v = (DrawingLabelAlignV)align_v;\n            }\n        }\n\n        free(obj);\n        cur += 10;\n    }\n\n    free(buf);\n    return true;\n}\n"
  },
  {
    "path": "src/alerts.c",
    "name": "alerts.c",
    "category": "source",
    "language": "c",
    "summary": "Évaluateur multi-conditions AND/OR temps réel avec cooldown, journal et alerte sonore.",
    "content": "#include \"alerts.h\"\n#include <stdio.h>\n#include <string.h>\n\nstatic bool read_metric(\n    AlertMetric m,\n    size_t idx,\n    const CandleBar* bars,\n    const IndicatorBuffers* ind,\n    const WatchlistItem* token_info,\n    double* out_val\n) {\n    switch (m) {\n        case METRIC_PRICE:       *out_val = bars[idx].close; return true;\n        case METRIC_EMA_FAST:    *out_val = ind->ema_fast[idx]; return ind->valid_ema_fast[idx];\n        case METRIC_EMA_SLOW:    *out_val = ind->ema_slow[idx]; return ind->valid_ema_slow[idx];\n        case METRIC_SMA:         *out_val = ind->sma[idx]; return ind->valid_sma[idx];\n        case METRIC_RSI:         *out_val = ind->rsi[idx]; return ind->valid_rsi[idx];\n        case METRIC_MACD:        *out_val = ind->macd_line[idx]; return ind->valid_macd[idx];\n        case METRIC_MACD_SIGNAL: *out_val = ind->macd_signal[idx]; return ind->valid_macd[idx];\n        case METRIC_BB_UPPER:    *out_val = ind->bb_upper[idx]; return ind->valid_bb[idx];\n        case METRIC_BB_LOWER:    *out_val = ind->bb_lower[idx]; return ind->valid_bb[idx];\n        case METRIC_SPREAD_BPS: {\n            if (!token_info || token_info->price <= 0.0) return false;\n            double lo = token_info->source_prices[0];\n            double hi = token_info->source_prices[0];\n            for (int s = 1; s < SRC_COUNT; s++) {\n                double p = token_info->source_prices[s];\n                if (p <= 0.0) continue;\n                if (lo <= 0.0 || p < lo) lo = p;\n                if (p > hi) hi = p;\n            }\n            if (lo <= 0.0 || hi <= 0.0) return false;\n            *out_val = ((hi - lo) / token_info->price) * 10000.0;\n            return true;\n        }\n    }\n    return false;\n}\n\nstatic bool eval_single(\n    const AlertCondition* c,\n    size_t cur_idx,\n    const CandleBar* bars,\n    const IndicatorBuffers* ind,\n    const WatchlistItem* token_info\n) {\n    if (cur_idx == 0) return false;\n    double l_cur = 0.0, l_prev = 0.0, r_cur = c->right_value, r_prev = c->right_value;\n\n    if (!read_metric(c->left_metric, cur_idx, bars, ind, token_info, &l_cur)) return false;\n    if (c->right_is_metric) {\n        if (!read_metric(c->right_metric, cur_idx, bars, ind, token_info, &r_cur)) return false;\n    }\n\n    switch (c->op) {\n        case OP_GT:  return l_cur > r_cur;\n        case OP_LT:  return l_cur < r_cur;\n        case OP_GTE: return l_cur >= r_cur;\n        case OP_LTE: return l_cur <= r_cur;\n        case OP_CROSS_ABOVE:\n            if (!read_metric(c->left_metric, cur_idx - 1, bars, ind, token_info, &l_prev)) return false;\n            if (c->right_is_metric &&\n                !read_metric(c->right_metric, cur_idx - 1, bars, ind, token_info, &r_prev)) return false;\n            return (l_prev <= r_prev) && (l_cur > r_cur);\n        case OP_CROSS_BELOW:\n            if (!read_metric(c->left_metric, cur_idx - 1, bars, ind, token_info, &l_prev)) return false;\n            if (c->right_is_metric &&\n                !read_metric(c->right_metric, cur_idx - 1, bars, ind, token_info, &r_prev)) return false;\n            return (l_prev >= r_prev) && (l_cur < r_cur);\n    }\n    return false;\n}\n\nvoid alerts_init(AlertEngine* engine) {\n    ZeroMemory(engine, sizeof(*engine));\n    engine->next_rule_id = 1;\n\n    AlertRule r = {0};\n    ov_wcscpy(r.name, 64, L\"Croisement EMA Haussier + RSI sain\");\n    ov_wcscpy(r.symbol, 24, L\"BTC/USDT\");\n    r.logic = LOGIC_AND;\n    r.enabled = true;\n    r.sound = true;\n    r.cooldown_ms = 60000;\n    r.condition_count = 2;\n    r.conditions[0] = (AlertCondition){\n        .left_metric     = METRIC_EMA_FAST,\n        .op              = OP_CROSS_ABOVE,\n        .right_is_metric = true,\n        .right_metric    = METRIC_EMA_SLOW\n    };\n    r.conditions[1] = (AlertCondition){\n        .left_metric     = METRIC_RSI,\n        .op              = OP_LT,\n        .right_is_metric = false,\n        .right_value     = 70.0\n    };\n    alerts_add_rule(engine, &r);\n}\n\nuint32_t alerts_add_rule(AlertEngine* engine, const AlertRule* rule) {\n    if (engine->rule_count >= MAX_ALERTS) return 0;\n    AlertRule* dst = &engine->rules[engine->rule_count++];\n    *dst = *rule;\n    dst->id = engine->next_rule_id++;\n    dst->last_fired_ms = 0;\n    dst->fire_count = 0;\n    return dst->id;\n}\n\nvoid alerts_toggle_rule(AlertEngine* engine, uint32_t id) {\n    for (size_t i = 0; i < engine->rule_count; i++) {\n        if (engine->rules[i].id == id) {\n            engine->rules[i].enabled = !engine->rules[i].enabled;\n            break;\n        }\n    }\n}\n\nvoid alerts_delete_rule(AlertEngine* engine, uint32_t id) {\n    for (size_t i = 0; i < engine->rule_count; i++) {\n        if (engine->rules[i].id == id) {\n            for (size_t j = i; j + 1 < engine->rule_count; j++) {\n                engine->rules[j] = engine->rules[j + 1];\n            }\n            engine->rule_count--;\n            break;\n        }\n    }\n}\n\nvoid alerts_clear_logs(AlertEngine* engine) {\n    engine->log_count = 0;\n}\n\nvoid alerts_evaluate(\n    AlertEngine* engine,\n    const wchar_t* symbol,\n    const CandleBar* bars,\n    size_t bar_count,\n    const IndicatorBuffers* ind,\n    const WatchlistItem* token_info,\n    int64_t now_ms,\n    HWND notify_hwnd\n) {\n    if (bar_count < 2) return;\n    size_t last = bar_count - 1;\n\n    for (size_t i = 0; i < engine->rule_count; i++) {\n        AlertRule* r = &engine->rules[i];\n        if (!r->enabled || wcscmp(r->symbol, symbol) != 0 || r->condition_count == 0) continue;\n        if (r->last_fired_ms > 0 && (now_ms - r->last_fired_ms) < r->cooldown_ms) continue;\n\n        bool matched = (r->logic == LOGIC_AND);\n        for (size_t c = 0; c < r->condition_count; c++) {\n            bool res = eval_single(&r->conditions[c], last, bars, ind, token_info);\n            if (r->logic == LOGIC_AND && !res) { matched = false; break; }\n            if (r->logic == LOGIC_OR && res)   { matched = true; break; }\n        }\n\n        if (matched) {\n            r->last_fired_ms = now_ms;\n            r->fire_count++;\n            if (engine->log_count >= MAX_ALERT_LOGS) {\n                memmove(&engine->logs[1], &engine->logs[0], (MAX_ALERT_LOGS - 1) * sizeof(AlertLogEntry));\n            } else {\n                if (engine->log_count > 0) {\n                    memmove(&engine->logs[1], &engine->logs[0], engine->log_count * sizeof(AlertLogEntry));\n                }\n                engine->log_count++;\n            }\n            AlertLogEntry* entry = &engine->logs[0];\n            ZeroMemory(entry, sizeof(*entry));\n            entry->rule_id = r->id;\n            ov_wcscpy(entry->rule_name, 64, r->name);\n            ov_wcscpy(entry->symbol, 24, r->symbol);\n            entry->price        = bars[last].close;\n            entry->timestamp_ms = now_ms;\n            swprintf(\n                entry->summary, 96, L\"%ls · %.2f · %ls\",\n                r->symbol, bars[last].close,\n                r->logic == LOGIC_AND ? L\"AND\" : L\"OR\"\n            );\n\n            if (r->sound) {\n                MessageBeep(MB_ICONASTERISK);\n            }\n            if (notify_hwnd) {\n                PostMessageW(notify_hwnd, WM_APP_ALERT_FIRED, (WPARAM)r->id, 0);\n            }\n        }\n    }\n}\n"
  },
  {
    "path": "src/export.c",
    "name": "export.c",
    "category": "source",
    "language": "c",
    "summary": "Exportation CSV (BOM UTF-8) et JSON complète via CreateFileW.",
    "content": "#include \"export.h\"\n#include <stdio.h>\n#include <string.h>\n\nstatic void write_str(HANDLE h, const char* s) {\n    DWORD written = 0;\n    WriteFile(h, s, (DWORD)strlen(s), &written, NULL);\n}\n\nstatic void wcs_to_utf8(const wchar_t* w, char* out, int out_cap) {\n    WideCharToMultiByte(CP_UTF8, 0, w ? w : L\"\", -1, out, out_cap, NULL, NULL);\n}\n\nstatic const char* source_name_utf8(FeedSourceId s) {\n    switch (s) {\n        case SRC_BINANCE:  return \"binance\";\n        case SRC_COINBASE: return \"coinbase\";\n        case SRC_KRAKEN:   return \"kraken\";\n        default:           return \"binance\";\n    }\n}\n\nbool export_candles_csv_w(\n    const wchar_t* file_path,\n    const wchar_t* symbol,\n    TimeframeSec timeframe,\n    FeedSourceId source,\n    const CandleBar* bars,\n    size_t count,\n    const IndicatorSettings* cfg,\n    const IndicatorBuffers* ind\n) {\n    HANDLE h = CreateFileW(\n        file_path, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL\n    );\n    if (h == INVALID_HANDLE_VALUE) return false;\n\n    const unsigned char bom[3] = { 0xEF, 0xBB, 0xBF };\n    DWORD written = 0;\n    WriteFile(h, bom, 3, &written, NULL);\n\n    char header[512];\n    snprintf(\n        header, sizeof(header),\n        \"timestamp_utc,symbol,timeframe,source,open,high,low,close,volume\"\n        \"%s%s%s%s%s%s\\r\\n\",\n        cfg->enable_ema_fast ? \",ema_fast\" : \"\",\n        cfg->enable_ema_slow ? \",ema_slow\" : \"\",\n        cfg->enable_sma      ? \",sma\" : \"\",\n        cfg->enable_bb       ? \",bb_upper,bb_mid,bb_lower\" : \"\",\n        cfg->enable_rsi      ? \",rsi\" : \"\",\n        cfg->enable_macd     ? \",macd,macd_signal,macd_hist\" : \"\"\n    );\n    write_str(h, header);\n\n    char sym_utf8[64], tf_utf8[16];\n    wcs_to_utf8(symbol, sym_utf8, sizeof(sym_utf8));\n    wcs_to_utf8(ov_tf_code(timeframe), tf_utf8, sizeof(tf_utf8));\n    const char* src_utf8 = source_name_utf8(source);\n\n    char line[768];\n    for (size_t i = 0; i < count; i++) {\n        const CandleBar* b = &bars[i];\n        int pos = snprintf(\n            line, sizeof(line),\n            \"%lld,%s,%s,%s,%.6f,%.6f,%.6f,%.6f,%.4f\",\n            (long long)b->time_utc, sym_utf8, tf_utf8, src_utf8,\n            b->open, b->high, b->low, b->close, b->volume\n        );\n        if (cfg->enable_ema_fast && pos > 0) {\n            pos += snprintf(line + pos, sizeof(line) - (size_t)pos, \",%.6f\",\n                            ind->valid_ema_fast[i] ? ind->ema_fast[i] : 0.0);\n        }\n        if (cfg->enable_ema_slow && pos > 0) {\n            pos += snprintf(line + pos, sizeof(line) - (size_t)pos, \",%.6f\",\n                            ind->valid_ema_slow[i] ? ind->ema_slow[i] : 0.0);\n        }\n        if (cfg->enable_sma && pos > 0) {\n            pos += snprintf(line + pos, sizeof(line) - (size_t)pos, \",%.6f\",\n                            ind->valid_sma[i] ? ind->sma[i] : 0.0);\n        }\n        if (cfg->enable_bb && pos > 0) {\n            pos += snprintf(line + pos, sizeof(line) - (size_t)pos, \",%.6f,%.6f,%.6f\",\n                            ind->valid_bb[i] ? ind->bb_upper[i] : 0.0,\n                            ind->valid_bb[i] ? ind->bb_mid[i] : 0.0,\n                            ind->valid_bb[i] ? ind->bb_lower[i] : 0.0);\n        }\n        if (cfg->enable_rsi && pos > 0) {\n            pos += snprintf(line + pos, sizeof(line) - (size_t)pos, \",%.2f\",\n                            ind->valid_rsi[i] ? ind->rsi[i] : 0.0);\n        }\n        if (cfg->enable_macd && pos > 0) {\n            pos += snprintf(line + pos, sizeof(line) - (size_t)pos, \",%.6f,%.6f,%.6f\",\n                            ind->valid_macd[i] ? ind->macd_line[i] : 0.0,\n                            ind->valid_macd[i] ? ind->macd_signal[i] : 0.0,\n                            ind->valid_macd[i] ? ind->macd_hist[i] : 0.0);\n        }\n        if (pos > 0 && (size_t)pos + 3 < sizeof(line)) {\n            strcat(line + pos, \"\\r\\n\");\n        }\n        write_str(h, line);\n    }\n\n    CloseHandle(h);\n    return true;\n}\n\nbool export_workspace_json_w(\n    const wchar_t* file_path,\n    uint32_t entry_id,\n    bool is_primary_entry,\n    const wchar_t* symbol,\n    TimeframeSec timeframe,\n    FeedSourceId source,\n    const CandleBar* bars,\n    size_t count,\n    const DrawingStore* drawings,\n    const AlertEngine* alerts\n) {\n    HANDLE h = CreateFileW(\n        file_path, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL\n    );\n    if (h == INVALID_HANDLE_VALUE) return false;\n\n    char sym_utf8[64], tf_utf8[16];\n    wcs_to_utf8(symbol, sym_utf8, sizeof(sym_utf8));\n    wcs_to_utf8(ov_tf_code(timeframe), tf_utf8, sizeof(tf_utf8));\n\n    char buf[512];\n    snprintf(\n        buf, sizeof(buf),\n        \"{\\n  \\\"symbol\\\": \\\"%s\\\",\\n  \\\"timeframe\\\": \\\"%s\\\",\\n  \\\"primarySource\\\": \\\"%s\\\",\\n  \\\"candleCount\\\": %zu,\\n  \\\"candles\\\": [\\n\",\n        sym_utf8, tf_utf8, source_name_utf8(source), count\n    );\n    write_str(h, buf);\n\n    for (size_t i = 0; i < count; i++) {\n        const CandleBar* b = &bars[i];\n        snprintf(\n            buf, sizeof(buf),\n            \"    {\\\"time\\\": %lld, \\\"open\\\": %.6f, \\\"high\\\": %.6f, \\\"low\\\": %.6f, \\\"close\\\": %.6f, \\\"volume\\\": %.4f}%s\\n\",\n            (long long)b->time_utc,\n            b->open, b->high, b->low, b->close, b->volume,\n            (i + 1 < count) ? \",\" : \"\"\n        );\n        write_str(h, buf);\n    }\n\n    write_str(h, \"  ],\\n  \\\"drawings\\\": [\\n\");\n    bool first_drw = true;\n    for (size_t d = 0; d < drawings->count; d++) {\n        const ChartDrawing* dr = &drawings->items[d];\n        if (!drawings_matches_scope(dr, entry_id, symbol, is_primary_entry)) continue;\n        if (!first_drw) write_str(h, \",\\n\");\n        first_drw = false;\n        char lbl_utf8[128];\n        wcs_to_utf8(dr->label, lbl_utf8, sizeof(lbl_utf8));\n        snprintf(\n            buf, sizeof(buf),\n            \"    {\\\"id\\\": %u, \\\"entryId\\\": %u, \\\"kind\\\": %d, \\\"color\\\": \\\"#%06X\\\", \\\"lineWidth\\\": %.1f, \\\"lineStyle\\\": %d, \\\"locked\\\": %s, \\\"p0_time\\\": %lld, \\\"p0_price\\\": %.6f, \\\"label\\\": \\\"%s\\\"}\",\n            dr->id, dr->entry_id, (int)dr->kind, (unsigned)(dr->argb_color & 0xFFFFFFU),\n            dr->stroke_width, (int)dr->line_style, dr->locked ? \"true\" : \"false\",\n            (long long)dr->pts[0].time_utc, dr->pts[0].price, lbl_utf8\n        );\n        write_str(h, buf);\n    }\n    write_str(h, \"\\n  ],\\n  \\\"alertRulesCount\\\": \");\n    snprintf(buf, sizeof(buf), \"%zu\\n}\\n\", alerts ? alerts->rule_count : 0);\n    write_str(h, buf);\n\n    CloseHandle(h);\n    return true;\n}\n"
  }
